```javascript
import * as THREE from 'three/webgpu';
import { texture, uv, vec3, color, uniform, mix, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-row';

  const pos = config.scenePosition || { x: 0, y: 0.7, z: 0 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  const colors = {
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
    surface: 0x0b0b10,
  };

  const rowWidth = 7.0;
  const rowHeight = 0.7;

  // background plane with brushed metal texture
  const geometry = new THREE.PlaneGeometry(rowWidth, rowHeight);
  const mat = new THREE.MeshBasicNodeMaterial({ transparent: true });

  let map = null;
  try {
    map = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
    map.colorSpace = THREE.SRGBColorSpace;
  } catch (e) {
    map = null;
  }

  const hoverUniform = uniform(0.0);
  const baseColor = color(colors.surface);
  const paperColor = color(colors.paper);

  if (map) {
    const texNode = texture(map, uv());
    const tintedTex = texNode.rgb.mul(baseColor.mul(2.0));
    mat.colorNode = mix(tintedTex, mix(tintedTex, paperColor, 0.15), hoverUniform);
  } else {
    mat.colorNode = mix(baseColor, mix(baseColor, paperColor, 0.1), hoverUniform);
  }
  mat.opacityNode = float(1.0);

  const rowMesh = new THREE.Mesh(geometry, mat);
  rowMesh.name = 'row-bg';
  group.add(rowMesh);

  // divider line (thin plane) at bottom of row
  const dividerGeo = new THREE.PlaneGeometry(rowWidth * 0.96, 0.012);
  const dividerMat = new THREE.MeshBasicNodeMaterial({ transparent: true });
  dividerMat.colorNode = color(colors.ink);
  dividerMat.opacityNode = float(0.35);
  const divider = new THREE.Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -rowHeight / 2 + 0.02, 0.001);
  divider.name = 'row-divider';
  group.add(divider);

  // Title text (placeholder generic label since no explicit textContent given)
  const titleText = (config.textContent && config.textContent.title) || 'Collection Item';
  const metaText = (config.textContent && config.textContent.meta) || '';

  let titleMesh = null;
  let metaMesh = null;

  if (ctx.fontAtlas && ctx.fontAtlas.createText) {
    titleMesh = ctx.fontAtlas.createText(titleText, {
      font: 'display',
      weight: 400,
      size: 0.2,
      color: colors.paper,
    });
    titleMesh.position.set(-rowWidth / 2 + 0.5, 0.05, 0.002);
    group.add(titleMesh);

    if (metaText) {
      metaMesh = ctx.fontAtlas.createText(metaText, {
        font: 'text',
        weight: 400,
        size: 0.13,
        color: colors.paper,
      });
      metaMesh.position.set(rowWidth / 2 - 1.6, 0.02, 0.002);
      group.add(metaMesh);
    }
  }

  // Accent edge indicator for focus (hidden by default, animated on hover)
  const accentGeo = new THREE.PlaneGeometry(0.04, rowHeight * 0.7);
  const accentMat = new THREE.MeshBasicNodeMaterial({ transparent: true });
  accentMat.colorNode = color(colors.accent);
  const accentOpacityUniform = uniform(0.0);
  accentMat.opacityNode = accentOpacityUniform;
  const accentEdge = new THREE.Mesh(accentGeo, accentMat);
  accentEdge.position.set(-rowWidth / 2 + 0.02, 0, 0.003);
  accentEdge.name = 'accent-edge';
  group.add(accentEdge);

  let hoverTl = null;
  let pressTl = null;

  const onHoverIn = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: pos.y + 0.15,
      duration: 0.4,
      ease: 'power3.out',
    }, 0);
    hoverTl.to(hoverUniform, { value: 1.0, duration: 0.4, ease: 'power2.out' }, 0);
    hoverTl.to(accentOpacityUniform, { value: 1.0, duration: 0.3, ease: 'power2.out' }, 0);
  };

  const onHoverOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: pos.y,
      duration: 0.4,
      ease: 'power3.out',
    }, 0);
    hoverTl.to(hoverUniform, { value: 0.0, duration: 0.4, ease: 'power2.out' }, 0);
    hoverTl.to(accentOpacityUniform, { value: 0.0, duration: 0.3, ease: 'power2.out' }, 0);
  };

  const onClick = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: scl.x * 0.97,
      y: scl.y * 0.97,
      z: scl.z * 0.97,
      duration: 0.12,
      ease: 'back.out',
    }).to(group.scale, {
      x: scl.x,
      y: scl.y,
      z: scl.z,
      duration: 0.2,
      ease: 'back.out',
    });

    if (ctx.emit) {
      ctx.emit('hub-collection.select', { source: 'hub-collection-row' });
    } else if (group.dispatchEvent) {
      group.dispatchEvent({ type: 'hub-collection.select' });
    }
  };

  group.userData.handlers = {
    onHoverIn,
    onHoverOut,
    onClick,
    onPointerOver: onHoverIn,
    onPointerOut: onHoverOut,
    onPointerDown: onClick,
  };

  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    geometry.dispose();
    mat.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    if (map) map.dispose();
    if (titleMesh && titleMesh.userData && titleMesh.userData.cleanup) {
      titleMesh.userData.cleanup();
    }
    if (metaMesh && metaMesh.userData && metaMesh.userData.cleanup) {
      metaMesh.userData.cleanup();
    }
  };

  return group;
}
